mapper.select:
SELECT COUNT(*)
FROM admin_announcement_read
WHERE announcement_id = #{announcementId}

SELECT COUNT(DISTINCT ar.announcement_id)
FROM admin_announcement_read ar
JOIN admin_announcement a ON a.id = ar.announcement_id
WHERE ar.user_id = #{userId}
  AND ar.user_type = #{userType}
  AND a.status = 'PUBLISHED'
